#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

static inline std::vector<int64_t> infer_avgpool3d_out_shape(const at::Tensor& x,
                                                             int64_t kernel_size,
                                                             int64_t stride,
                                                             int64_t padding) {
    auto sizes = x.sizes();
    int64_t n = sizes[0];
    int64_t c = sizes[1];
    int64_t d = sizes[2];
    int64_t h = sizes[3];
    int64_t w = sizes[4];

    if (stride <= 0) stride = kernel_size;
    int64_t od = (d + 2 * padding - kernel_size) / stride + 1;
    int64_t oh = (h + 2 * padding - kernel_size) / stride + 1;
    int64_t ow = (w + 2 * padding - kernel_size) / stride + 1;
    if (od < 0) od = 0;
    if (oh < 0) oh = 0;
    if (ow < 0) ow = 0;
    return {n, c, od, oh, ow};
}

at::Tensor average_pooling_3d_custom_impl_npu(const at::Tensor& x,
                                              int64_t kernel_size,
                                              int64_t stride,
                                              int64_t padding) {
    TORCH_CHECK(x.dim() == 5, "average_pooling_3d_custom expects 5D input (N, C, D, H, W)");
    auto out_shape = infer_avgpool3d_out_shape(x, kernel_size, stride, padding);
    at::Tensor y = at::empty(out_shape, x.options());

    EXEC_NPU_CMD(aclnnAveragePooling3dCustom, x, y, kernel_size, stride, padding);
    return y;
}

